div.style:
border:1px solid #dbe3ec;
border-radius:16px;
background:#ffffff;
box-shadow:
    0 10px 30px rgba(1,16,39,0.12),
    0 3px 8px rgba(1,16,39,0.08);
overflow:hidden;

width:110px;
height:110px;
margin:auto;
margin-top:-40px;
border-radius:50%;
overflow:hidden;
border:4px solid white;
background:white;
box-shadow:
    0 6px 18px rgba(0,0,0,0.20),
    0 0 0 3px rgba(0,160,157,0.15);

span.style:
background:#eef6ff;
color:#0d6efd;
padding:4px 12px;
border-radius:20px;
font-size:11px;
font-weight:700;
margin-right:5px;
display:inline-block;

background:#f5f7fa;
color:#495057;
padding:4px 12px;
border-radius:20px;
font-size:11px;
font-weight:700;
display:inline-block;

div.style:
margin-top:18px;
margin-bottom:12px;
padding:10px 12px;
background:#f8fafc;
border-left:4px solid #00A09D;
border-radius:6px;
